('main', 'Ring Size Guide', 'find-your-ring-size', 'PUBLISHED', 'FIND YOUR PERFECT RING SIZE', 'Comprehensive Floksy Jewel Sizing Guide', NULL, 'center', '#19202A', 'Request Free Ring Sizer', '#free-sizer', 'Precision Sizing for Life\'s Timeless Moments', NULL, NULL, 'International Ring Size Conversion', 'Measure your finger diameter or convert existing ring sizes using our standardized international chart.', NULL, 'Ring Size Measurement Chart', 'Print at 100% scale to match your existing rings directly.', NULL, 'COMPLIMENTARY FLOKSY RING SIZER', 'Receive our reusable precision ring sizer delivered directly to your door.', NULL, 'REQUEST FREE SIZER', '#request-sizer', 'HOW TO MEASURE AT HOME', 'Follow these three simple steps using a strip of paper or string.', NULL, 'NEED EXPERT SIZING ASSISTANCE?', 'Our Mayfair atelier master jewellers are available 7 days a week.', 'BOOK ATELIER CONSULTATION', '/contact-us', '#19202A', 'Ring Size Guide | Floksy Jewel', 'Find your perfect ring size with Floksy Jewel\'s comprehensive international ring size conversion chart and complimentary sizer.', 'ring size guide, ring sizer, international ring sizes, measure ring size', 'https://floksyjewel.com/education/rings/find-your-ring-size', NULL, NULL, NULL, '2026-08-10 05:22:27.970', '2026-08-10 05:22:27.970');
